Scripts/AnimalView.gd:
class_name AnimalView
extends Node2D

@export var base_color := Color("#b8d94b")
@export var behavior_colors: Dictionary = {}
@export var vision_color := Color(0.7, 0.8, 0.7, 0.08)
@export var debug_line_width: float = 1.0
@export_range(0.1, 3.0, 0.1) var howl_visual_duration: float = 0.8
@export var howl_color := Color(1.0, 0.65, 0.2, 0.65)
@onready var sprite: Sprite2D = $Sprite2D
@onready var bt_player: BTPlayer = $BTPlayer

var entity: AnimalEntity
var _last_behavior: int = -1
var _last_alive: bool = true

func sync() -> void:
	var data: AnimalData = g_gameplayEngine.entity_service.data
	if global_position != data.motion_position[entity.row]:
		global_position = data.motion_position[entity.row]
	var angle := data.motion_facing[entity.row].angle() + PI * 0.5
	if not is_equal_approx(sprite.rotation, angle):
		sprite.rotation = angle
	var behavior := data.brain_current_behavior[entity.row]
	var alive: bool = data.identity_alive[entity.row] != 0
	if behavior != _last_behavior or alive != _last_alive:
		sprite.self_modulate = behavior_colors.get(AnimalEntity.BEHAVIOR_NAMES[behavior], base_color) if alive else Color("#7b8794")
		_last_behavior = behavior
		_last_alive = alive

func reset_tree() -> void:
	bt_player.restart()
	bt_player.active = false
	var blackboard := bt_player.get_blackboard()
	for key in blackboard.list_vars():
		blackboard.erase_var(key)

Scripts/RootController.gd:
extends Node2D

@export var simulation_config: SimulationConfig
@onready var world: Node2D = $World
@onready var hud: DebugHUD = $DebugHUD
@onready var camera: Camera2D = $Camera2D

func _ready() -> void:
	# 1) 场地和 HUD 就绪后再启动服务与模拟。
	g_gameplayEngine.configuration_applied.connect(_refresh_world)
	g_gameplayEngine.start_simulation(world, hud, simulation_config)
	get_viewport().size_changed.connect(_refresh_camera)
	_refresh_world(false)

func _refresh_world(_restarted: bool) -> void:
	var size: Vector2 = g_gameplayEngine.config.arena_size
	$World/Ground.polygon = PackedVector2Array([Vector2.ZERO, Vector2(size.x, 0), size, Vector2(0, size.y)])
	_refresh_camera()

func _refresh_camera() -> void:
	var size: Vector2 = g_gameplayEngine.config.arena_size
	var viewport_size := get_viewport_rect().size
	camera.position = size * 0.5
	camera.zoom = Vector2.ONE * minf(viewport_size.x / size.x, viewport_size.y / size.y)

func _exit_tree() -> void:
	if is_instance_valid(g_gameplayEngine):
		g_gameplayEngine.stop_simulation()

Scripts/Core/DebugService.gd:
class_name DebugService
extends Service

var hud: DebugHUD
var hud_enabled: bool = true
var overlay_enabled: bool = true
var _selected: AnimalEntity
var selected: AnimalEntity:
	get:
		return g_gameplayEngine.entity_service.data.live(_selected)
	set(value):
		_selected = value
var show_details: bool = false:
	set(value):
		show_details = value
		if not value:
			howl_events.clear()
		queue_redraw()
var selected_only: bool = true
var visual_options: Dictionary[String, bool] = {
	"wolf_vision": true, "dog_vision": true,
	"tracking": true, "memory": true, "movement": true,
	"protection": true, "howl": true,
}
var howl_events: Array[Dictionary] = []

func _startup() -> void:
	clear_selection()
	hud.initialize(g_gameplayEngine)

func _reset() -> void:
	clear_selection()
	howl_events.clear()

func _shutdown() -> void:
	clear_selection()
	howl_events.clear()
	hud = null

func _process(_delta: float) -> void:
	if not started or not g_gameplayEngine.running:
		return
	if overlay_enabled:
		refresh()
	if hud_enabled and is_instance_valid(hud):
		var started := Time.get_ticks_usec() if g_gameplayEngine.profile_service.performance_stats_enabled else 0
		hud.refresh()
		if g_gameplayEngine.profile_service.performance_stats_enabled:
			g_gameplayEngine.profile_service.record_debug_time("HUDRefresh", started)

func _unhandled_input(event: InputEvent) -> void:
	if not started or not g_gameplayEngine.running:
		return

	if event is InputEventKey and event.pressed and not event.echo:
		if get_viewport().gui_get_focus_owner() is LineEdit:
			return

		var key: int = event.physical_keycode if event.physical_keycode != 0 else event.keycode
		var amount := 10 if event.shift_pressed else 1
		match key:
			KEY_1:
				g_gameplayEngine.request_spawn(AnimalEntity.Kind.SHEEP, amount)
			KEY_2:
				g_gameplayEngine.request_spawn(AnimalEntity.Kind.WOLF, amount)
			KEY_3:
				g_gameplayEngine.request_spawn(AnimalEntity.Kind.SHEEPDOG, amount)
			KEY_SPACE:
				g_gameplayEngine.paused = not g_gameplayEngine.paused
			KEY_N:
				g_gameplayEngine.request_single_step()
			KEY_R:
				g_gameplayEngine.request_reset()
			KEY_F1:
				show_details = not show_details
			_:
				return
		get_viewport().set_input_as_handled()
	elif event is InputEventMouseButton and event.pressed and event.button_index == MOUSE_BUTTON_LEFT:
		select_at(get_global_mouse_position())
		get_viewport().set_input_as_handled()

func select_at(point: Vector2) -> void:
	var data: AnimalData = g_gameplayEngine.entity_service.data
	selected = null
	var nearest_distance: float = 19.0
	for animal in g_gameplayEngine.entity_service.entities:
		if data.identity_alive[animal.row]:
			var distance := point.distance_to(data.motion_position[animal.row])
			if distance < nearest_distance:
				selected = animal
				nearest_distance = distance
	queue_redraw()

func clear_selection() -> void:
	selected = null
	queue_redraw()

func clear_invalid_selection() -> void:
	var data: AnimalData = g_gameplayEngine.entity_service.data
	if not is_instance_valid(selected) or not data.identity_alive[selected.row]:
		selected = null

func refresh() -> void:
	clear_invalid_selection()
	queue_redraw()

func selection_text() -> String:
	var data: AnimalData = g_gameplayEngine.entity_service.data
	if not is_instance_valid(selected):
		return "Click an animal to inspect its behavior and target."
	var target_text := "none"
	if g_gameplayEngine.animal_system.is_live(selected, data.live(data.memory_target[selected.row])):
		target_text = "%s #%d" % [AnimalEntity.KIND_NAMES[data.identity_kind[data.live(data.memory_target[selected.row]).row]], data.identity_entity_id[data.live(data.memory_target[selected.row]).row]]
	var text := "%s #%d  |  %s  |  Target: %s" % [
		AnimalEntity.KIND_NAMES[data.identity_kind[selected.row]], data.identity_entity_id[selected.row],
		AnimalEntity.BEHAVIOR_NAMES[data.brain_current_behavior[selected.row]], target_text]
	var details: String = g_gameplayEngine.debug_details(selected)
	if not details.is_empty():
		text += "  |  " + details
	return text

func set_visual_option(key: String, value: bool) -> void:
	visual_options[key] = value
	if key == "howl" and not value:
		howl_events.clear()
	queue_redraw()

func record_howl(animal: AnimalEntity) -> void:
	var data: AnimalData = g_gameplayEngine.entity_service.data
	var row := animal.row
	if not overlay_enabled or not show_details or not visual_options["howl"]:
		return
	if selected_only and selected != animal:
		return
	var view := data.brain_view[row]
	howl_events.append({
		"position": data.motion_position[row], "radius": data.settings[row].howl_radius,
		"duration": view.howl_visual_duration, "elapsed": 0.0,
		"color": view.howl_color, "id": data.identity_entity_id[row],
		"uid": animal.uid,
	})

func advance_visuals(delta: float) -> void:
	if not overlay_enabled or not show_details or not visual_options["howl"]:
		howl_events.clear()
		return
	for index in range(howl_events.size() - 1, -1, -1):
		howl_events[index]["elapsed"] += delta
		if howl_events[index]["elapsed"] >= howl_events[index]["duration"]:
			howl_events.remove_at(index)

func _draw() -> void:
	var data: AnimalData = g_gameplayEngine.entity_service.data
	if not started or not g_gameplayEngine.running or not overlay_enabled:
		return
	var started_at := Time.get_ticks_usec() if g_gameplayEngine.profile_service.performance_stats_enabled else 0
	if selected != null:
		draw_arc(data.motion_position[selected.row], 17.0, 0.0, TAU, 40, Color("#f4f7ed"), 2.0, true)
	if show_details:
		if selected_only:
			if selected != null:
				_draw_animal(selected)
		else:
			for animal in g_gameplayEngine.entity_service.entities:
				if animal.enabled and data.identity_alive[animal.row]:
					_draw_animal(animal)
		if visual_options["howl"]:
			for event in howl_events:
				if selected_only and (selected == null or selected.uid != event["uid"]):
					continue
				var progress: float = clampf(event["elapsed"] / event["duration"], 0.0, 1.0)
				var color: Color = event["color"]
				color.a *= 1.0 - progress
				draw_circle(event["position"], event["radius"], Color(color, color.a * 0.08))
				draw_arc(event["position"], event["radius"], 0.0, TAU, 48, Color(color, color.a * 0.4), 1.0, true)
				draw_arc(event["position"], event["radius"] * progress, 0.0, TAU, 48, color, 2.0, true)
	if g_gameplayEngine.profile_service.performance_stats_enabled:
		g_gameplayEngine.profile_service.record_debug_time("OverlayDrawCPUTime", started_at)

func _draw_animal(animal: AnimalEntity) -> void:
	var data: AnimalData = g_gameplayEngine.entity_service.data
	var row := animal.row
	var point := data.motion_position[row]
	var view := data.brain_view[row]
	var width := view.debug_line_width
	var vision_key: String = ["", "wolf_vision", "dog_vision"][data.identity_kind[row]]
	if data.identity_kind[row] != AnimalEntity.Kind.SHEEP and visual_options[vision_key]:
		var half_angle: float = deg_to_rad(data.settings[row].vision_angle * 0.5)
		var radius: float = data.settings[row].perception_radius
		var direction := data.motion_facing[row].angle()
		var points := PackedVector2Array([point])
		for index in range(33):
			points.append(point + Vector2.from_angle(direction - half_angle + 2.0 * half_angle * index / 32.0) * radius)
		draw_colored_polygon(points, view.vision_color)
		var edge := Color(view.vision_color, 0.5)
		draw_arc(point, radius, direction - half_angle, direction + half_angle, 32, edge, width, true)
		draw_line(point, points[1], edge, width, true)
		draw_line(point, points[-1], edge, width, true)
	if data.live(data.memory_target[row]) != null:
		if visual_options["tracking"]:
			if data.memory_target_visible[row]:
				draw_line(point, data.memory_last_seen_position[row], Color(view.base_color, 0.5), width, true)
			else:
				draw_dashed_line(point, data.memory_last_seen_position[row], Color(view.base_color, 0.5), width, 6.0)
		if visual_options["memory"] and not data.memory_target_visible[row]:
			var remaining: float = clampf(1.0 - data.memory_unseen_elapsed[row] / maxf(data.settings[row].memory_duration, 0.00001), 0.0, 1.0)
			var color := Color(view.base_color, remaining)
			draw_arc(data.memory_last_seen_position[row], 7.0, 0.0, TAU, 20, color, width, true)
			draw_line(data.memory_last_seen_position[row] - Vector2(4, 0), data.memory_last_seen_position[row] + Vector2(4, 0), color, width)
			draw_line(data.memory_last_seen_position[row] - Vector2(0, 4), data.memory_last_seen_position[row] + Vector2(0, 4), color, width)
	if visual_options["movement"]:
		if not visual_options["tracking"] or data.live(data.memory_target[row]) == null or not data.motion_movement_goal[row].is_equal_approx(data.memory_last_seen_position[row]):
			draw_line(point, data.motion_movement_goal[row], Color("#f4f7ed"), width, true)
		draw_circle(data.motion_movement_goal[row], 3.0, Color("#f4f7ed"))
	if visual_options["protection"] and data.identity_kind[row] == AnimalEntity.Kind.SHEEPDOG:
		draw_arc(data.dog_protection_center[row], data.settings[row].local_flock_radius, 0.0, TAU, 48, Color("#93c5fd"), width, true)
		draw_circle(data.dog_protection_center[row], 4.0, Color("#93c5fd"))
		draw_circle(data.dog_guard_point[row], 4.0, Color("#93c5fd"), false, width, true)
		if data.live(data.dog_collected_sheep[row]) != null:
			draw_dashed_line(point, data.motion_position[data.live(data.dog_collected_sheep[row]).row], Color("#4de6b3"), width, 6.0)

Scripts/Core/GridService.gd:
class_name GridService
extends Service

var cell_size: float = 30.0
var width: int = 0
var height: int = 0

var perception_positions := PackedVector2Array()
var perception_velocities := PackedVector2Array()
var perception_kinds := PackedInt32Array()
var row_cells := PackedInt32Array()
var cell_counts := PackedInt32Array()
var cell_offsets := PackedInt32Array()
var members := PackedInt32Array()

var sheep_position_sums := PackedVector2Array()
var sheep_velocity_sums := PackedVector2Array()
var flock_counts := PackedInt32Array()
var flock_position_sums := PackedVector2Array()
var alignment_counts := PackedInt32Array()
var alignment_velocity_sums := PackedVector2Array()

var _cursors := PackedInt32Array()
var _flock_offsets := PackedInt32Array()
var _alignment_offsets := PackedInt32Array()
var _flock_radius: float = -1.0
var _alignment_radius: float = -1.0
var _offset_cell_size: float = -1.0

var spatial_stats_enabled: bool = OS.is_debug_build()
var spatial_query_count: int = 0
var spatial_candidate_count: int = 0
var spatial_max_candidates: int = 0
var spatial_nonempty_cells: int = 0
var spatial_max_occupancy: int = 0

func rebuild() -> void:
	var data: AnimalData = g_gameplayEngine.entity_service.data
	var config: SimulationConfig = g_gameplayEngine.config
	cell_size = config.grid_cell_size
	width = ceili(config.arena_size.x / cell_size)
	height = ceili(config.arena_size.y / cell_size)
	var cells := width * height
	reset_spatial_stats()
	cell_counts.resize(cells * 3)
	cell_counts.fill(0)
	cell_offsets.resize(cells * 3 + 1)
	_cursors.resize(cells * 3)
	members.resize(data.active_count)
	row_cells.resize(data.active_count)
	perception_positions.resize(data.active_count)
	perception_velocities.resize(data.active_count)
	perception_kinds.resize(data.active_count)
	sheep_position_sums.resize(cells)
	sheep_position_sums.fill(Vector2.ZERO)
	sheep_velocity_sums.resize(cells)
	sheep_velocity_sums.fill(Vector2.ZERO)
	# 1) Count members by cell and species, and accumulate sheep statistics.
	for row in range(data.active_count):
		var point := data.motion_position[row]
		var cell := cell_at(point)
		var kind := data.identity_kind[row]
		row_cells[row] = cell
		perception_positions[row] = point
		perception_velocities[row] = data.motion_velocity[row]
		perception_kinds[row] = kind
		cell_counts[cell * 3 + kind] += 1
		if kind == AnimalEntity.Kind.SHEEP:
			sheep_position_sums[cell] += point
			sheep_velocity_sums[cell] += data.motion_velocity[row]
	# 2) Pack members into contiguous cell/species ranges in row order.
	cell_offsets[0] = 0
	for bucket in range(cells * 3):
		cell_offsets[bucket + 1] = cell_offsets[bucket] + cell_counts[bucket]
		_cursors[bucket] = cell_offsets[bucket]
	for row in range(data.active_count):
		var bucket := row_cells[row] * 3 + perception_kinds[row]
		members[_cursors[bucket]] = row
		_cursors[bucket] += 1
	if spatial_stats_enabled:
		for cell in range(cells):
			var count := cell_counts[cell * 3] + cell_counts[cell * 3 + 1] + cell_counts[cell * 3 + 2]
			if count > 0:
				spatial_nonempty_cells += 1
				spatial_max_occupancy = maxi(spatial_max_occupancy, count)
	# 3) Share flock and alignment sums between sheep in the same cell.
	if _offset_cell_size != cell_size or _flock_radius != config.sheep.flock_radius or _alignment_radius != config.sheep.alignment_radius:
		_flock_offsets = _make_offsets(config.sheep.flock_radius)
		_alignment_offsets = _make_offsets(config.sheep.alignment_radius)
		_offset_cell_size = cell_size
		_flock_radius = config.sheep.flock_radius
		_alignment_radius = config.sheep.alignment_radius
	flock_counts.resize(cells)
	flock_counts.fill(0)
	flock_position_sums.resize(cells)
	flock_position_sums.fill(Vector2.ZERO)
	alignment_counts.resize(cells)
	alignment_counts.fill(0)
	alignment_velocity_sums.resize(cells)
	alignment_velocity_sums.fill(Vector2.ZERO)
	for cell in range(cells):
		if cell_counts[cell * 3 + AnimalEntity.Kind.SHEEP] == 0:
			continue
		var x := cell % width
		var y := cell / width
		for offset in range(0, _flock_offsets.size(), 2):
			var nx := x + _flock_offsets[offset]
			var ny := y + _flock_offsets[offset + 1]
			if nx >= 0 and nx < width and ny >= 0 and ny < height:
				var neighbor := ny * width + nx
				flock_counts[cell] += cell_counts[neighbor * 3 + AnimalEntity.Kind.SHEEP]
				flock_position_sums[cell] += sheep_position_sums[neighbor]
		for offset in range(0, _alignment_offsets.size(), 2):
			var nx := x + _alignment_offsets[offset]
			var ny := y + _alignment_offsets[offset + 1]
			if nx >= 0 and nx < width and ny >= 0 and ny < height:
				var neighbor := ny * width + nx
				alignment_counts[cell] += cell_counts[neighbor * 3 + AnimalEntity.Kind.SHEEP]
				alignment_velocity_sums[cell] += sheep_velocity_sums[neighbor]

func cell_at(point: Vector2) -> int:
	var x := clampi(floori(point.x / cell_size), 0, width - 1)
	var y := clampi(floori(point.y / cell_size), 0, height - 1)
	return y * width + x

func _make_offsets(radius: float) -> PackedInt32Array:
	var offsets := PackedInt32Array()
	var extent := ceili(radius / cell_size)
	for y in range(-extent, extent + 1):
		for x in range(-extent, extent + 1):
			if Vector2(x, y).length_squared() * cell_size * cell_size <= radius * radius:
				offsets.append(x)
				offsets.append(y)
	return offsets

# Return broad-phase snapshot rows, optionally restricted to one species.
# e.g. get_nearby_indices(Vector2(300, 300), 24.0, AnimalEntity.Kind.SHEEP)
func get_nearby_indices(point: Vector2, radius: float, kind: int = -1) -> PackedInt32Array:
	var started_at := Time.get_ticks_usec() if g_gameplayEngine.profile_service.detailed_stats_enabled else 0
	var nearby := PackedInt32Array()
	var first := Vector2i(((point - Vector2.ONE * radius) / cell_size).floor()).max(Vector2i.ZERO)
	var last := Vector2i(((point + Vector2.ONE * radius) / cell_size).floor()).min(Vector2i(width - 1, height - 1))
	for y in range(first.y, last.y + 1):
		for x in range(first.x, last.x + 1):
			var bucket := (y * width + x) * 3
			var begin := cell_offsets[bucket + kind] if kind >= 0 else cell_offsets[bucket]
			var end := cell_offsets[bucket + kind + 1] if kind >= 0 else cell_offsets[bucket + 3]
			for member in range(begin, end):
				nearby.append(members[member])
	if spatial_stats_enabled:
		spatial_query_count += 1
		spatial_candidate_count += nearby.size()
		spatial_max_candidates = maxi(spatial_max_candidates, nearby.size())
	if g_gameplayEngine.profile_service.detailed_stats_enabled:
		g_gameplayEngine.profile_service.record_hotspot("NearbyQuery", started_at)
	return nearby

# Average sheep positions in cells whose centers lie inside the radius.
# e.g. sheep_center(Vector2(300, 300), 120.0)
func sheep_center(point: Vector2, radius: float) -> Vector2:
	var first := Vector2i(((point - Vector2.ONE * radius) / cell_size).floor()).max(Vector2i.ZERO)
	var last := Vector2i(((point + Vector2.ONE * radius) / cell_size).floor()).min(Vector2i(width - 1, height - 1))
	var sum := Vector2.ZERO
	var count := 0
	for y in range(first.y, last.y + 1):
		for x in range(first.x, last.x + 1):
			if (Vector2(x + 0.5, y + 0.5) * cell_size).distance_squared_to(point) <= radius * radius:
				var cell := y * width + x
				sum += sheep_position_sums[cell]
				count += cell_counts[cell * 3 + AnimalEntity.Kind.SHEEP]
	return sum / count if count > 0 else point

func reset_spatial_stats() -> void:
	spatial_query_count = 0
	spatial_candidate_count = 0
	spatial_max_candidates = 0
	spatial_nonempty_cells = 0
	spatial_max_occupancy = 0

func _reset() -> void:
	width = 0
	height = 0
	perception_positions.clear()
	perception_velocities.clear()
	perception_kinds.clear()
	row_cells.clear()
	cell_counts.clear()
	cell_offsets.clear()
	members.clear()
	_cursors.clear()
	sheep_position_sums.clear()
	sheep_velocity_sums.clear()
	flock_counts.clear()
	flock_position_sums.clear()
	alignment_counts.clear()
	alignment_velocity_sums.clear()
	reset_spatial_stats()

func _shutdown() -> void:
	_reset()

