class_name DebugHUD
extends CanvasLayer

@onready var metrics: Label = $Screen/Header/Metrics
@onready var status: Label = $Screen/Header/Status
@onready var selection: Label = $Screen/Footer/Selection
@onready var parameters: RuntimeConfigPanel = $Screen/Parameters
@onready var debug_panel: DebugPanel = $Screen/DebugPanel
var gameplay_engine: Node

func initialize(engine: Node) -> void:
	gameplay_engine = engine
	parameters.initialize(engine)
	debug_panel.initialize(engine.debug_service)
	if not $Screen/Header/ParametersButton.pressed.is_connected(_toggle_parameters):
		$Screen/Header/ParametersButton.pressed.connect(_toggle_parameters)
		$Screen/Header/DebugButton.pressed.connect(_toggle_debug)
	refresh()

func _unhandled_key_input(event: InputEvent) -> void:
	if event is InputEventKey and event.pressed and not event.echo:
		match event.keycode:
			KEY_F2:
				_toggle_parameters()
				get_viewport().set_input_as_handled()
			KEY_F3:
				_toggle_debug()
				get_viewport().set_input_as_handled()
			KEY_ESCAPE:
				if debug_panel.visible:
					debug_panel.close()
					get_viewport().set_input_as_handled()
				elif parameters.visible:
					parameters.close()
					get_viewport().set_input_as_handled()

func _toggle_parameters() -> void:
	debug_panel.close()
	parameters.toggle()

func _toggle_debug() -> void:
	parameters.close()
	debug_panel.toggle()

func refresh() -> void:
	var data: AnimalData = g_gameplayEngine.entity_service.data
	var counts: Vector3i = gameplay_engine.entity_service.get_counts()
	metrics.text = "FPS %d    |    Step %.2f ms    |    Alive %d    |    Sheep %d   Wolves %d   Dogs %d" % [
		Engine.get_frames_per_second(), gameplay_engine.profile_service.last_step_ms,
		counts.x + counts.y + counts.z, counts.x, counts.y, counts.z]
	var hunters: int = 0
	for wolf_row in gameplay_engine.entity_service.wolf_rows:
		var wolf := data.handles[wolf_row]
		if data.identity_alive[wolf.row] and data.wolf_hunting[wolf.row]:
			hunters += 1
	status.text = "%s    |    Seed %d    |    Sim %.1f s    |    Captured %d    |    %s    |    Debug %s" % [
		"PAUSED" if gameplay_engine.paused else "RUNNING", gameplay_engine.config.random_seed,
		gameplay_engine.simulation_time, gameplay_engine.entity_service.capture_count,
		"Hunting %d" % hunters,
		"ON" if gameplay_engine.debug_service.show_details else "OFF"]
	selection.text = gameplay_engine.debug_service.selection_text()
	parameters.refresh()
	if debug_panel.visible:
		debug_panel.refresh()

Scripts/ECS/Systems/AnimalSystem.gd:
class_name AnimalSystem
extends RefCounted

var data: AnimalData

func _init(storage: AnimalData) -> void:
	data = storage

func update_movement(delta: float) -> void:
	var lower := Vector2(12.0, 94.0)
	var upper: Vector2 = g_gameplayEngine.config.arena_size - Vector2(12.0, 58.0)
	for row in range(data.active_count):
		var previous := data.motion_position[row]
		var separation := Vector2.ZERO
		if data.identity_kind[row] != AnimalEntity.Kind.SHEEP:
			separation = data.motion_separation[row] * data.settings[row].move_speed
		var velocity := (data.motion_desired_velocity[row] + separation).limit_length(data.motion_speed_limit[row])
		var position := (previous + velocity * delta).clamp(lower, upper)
		velocity = (position - previous) / maxf(delta, 0.00001)
		data.motion_position[row] = position
		data.motion_velocity[row] = velocity
		if not velocity.is_zero_approx():
			data.motion_facing[row] = velocity.normalized()

func is_live(animal: AnimalEntity, other: AnimalEntity) -> bool:
	return data.live(other) != null

func can_see(animal: AnimalEntity, point: Vector2) -> bool:
	var row := animal.row
	var offset := point - data.motion_position[row]
	if offset.length_squared() > data.memory_vision_radius_squared[row]:
		return false
	return offset.is_zero_approx() or data.motion_facing[row].dot(offset.normalized()) + 0.000001 >= data.memory_vision_cos[row]

func observe_target(animal: AnimalEntity, delta: float) -> void:
	var memory_target_visible := data.memory_target_visible
	var memory_unseen_elapsed := data.memory_unseen_elapsed
	var row := animal.row
	var target := data.live(data.memory_target[row])
	if target == null:
		memory_target_visible[row] = 0
		memory_unseen_elapsed[row] = 0.0
		return
	memory_target_visible[row] = int(can_see(animal, data.motion_position[target.row]))
	if memory_target_visible[row]:
		data.memory_last_seen_position[row] = data.motion_position[target.row]
		data.memory_last_seen_velocity[row] = data.motion_velocity[target.row]
		memory_unseen_elapsed[row] = 0.0
	else:
		memory_unseen_elapsed[row] += delta

func perceive(animal: AnimalEntity, delta: float) -> void:
	var memory_perception_ready := data.memory_perception_ready
	var memory_perception_remaining := data.memory_perception_remaining
	var row := animal.row
	data.motion_wander_remaining[row] -= delta
	memory_perception_remaining[row] -= delta
	if not memory_perception_ready[row] or memory_perception_remaining[row] <= 0.0:
		var service: GridService = g_gameplayEngine.grid_service
		data.memory_nearby[row] = service.get_nearby_indices(data.motion_position[row], g_gameplayEngine.config.separation_distance, data.identity_kind[row])
		var started := Time.get_ticks_usec() if g_gameplayEngine.profile_service.detailed_stats_enabled else 0
		_scan_separation(animal, service)
		if g_gameplayEngine.profile_service.detailed_stats_enabled:
			g_gameplayEngine.profile_service.record_hotspot("Separation", started)
		memory_perception_remaining[row] = g_gameplayEngine.config.perception_interval
		if not memory_perception_ready[row]:
			memory_perception_remaining[row] *= fmod(data.identity_entity_id[row] * 0.618034, 1.0)
		memory_perception_ready[row] = 1
	if data.identity_kind[row] == AnimalEntity.Kind.SHEEP:
		var started := Time.get_ticks_usec() if g_gameplayEngine.profile_service.detailed_stats_enabled else 0
		g_gameplayEngine.sheep_system._scan_neighbors(animal, g_gameplayEngine.grid_service)
		if g_gameplayEngine.profile_service.detailed_stats_enabled:
			g_gameplayEngine.profile_service.record_hotspot("NeighborScan", started)

func _scan_separation(animal: AnimalEntity, service: GridService) -> void:
	var row := animal.row
	data.motion_separation[row] = Vector2.ZERO
	var distance_limit: float = g_gameplayEngine.config.separation_distance
	if distance_limit <= 0.0:
		return

	var position := data.motion_position[row]
	var kind := data.identity_kind[row]
	var entity_id := data.identity_entity_id[row]
	var positions := service.perception_positions
	var kinds := service.perception_kinds
	var separation := Vector2.ZERO
	for index in data.memory_nearby[row]:
		if index == row or kinds[index] != kind:
			continue

		var offset := position - positions[index]
		var distance_squared := offset.length_squared()
		if distance_squared >= distance_limit * distance_limit:
			continue

		var distance := sqrt(distance_squared)
		var direction := offset.normalized()
		if distance < 0.001:
			direction = Vector2.RIGHT if entity_id < data.identity_entity_id[index] else Vector2.LEFT
		separation += direction * (1.0 - distance / distance_limit)
	data.motion_separation[row] = separation

func decide(animal: AnimalEntity, delta: float) -> void:
	var row := animal.row
	var settings: Resource = data.settings[row]
	data.motion_desired_velocity[row] = Vector2.ZERO
	data.motion_speed_limit[row] = settings.move_speed
	data.brain_player[row].update(delta)

func get_wander_point(animal: AnimalEntity, distance: float) -> Vector2:
	var motion_wander_point := data.motion_wander_point
	var row := animal.row
	if data.motion_wander_remaining[row] <= 0.0 or data.motion_position[row].distance_to(motion_wander_point[row]) < 15.0:
		var direction := Vector2.from_angle(g_gameplayEngine.rng.randf_range(-PI, PI))
		motion_wander_point[row] = clamp_to_arena(animal, data.motion_position[row] + direction * distance)
		data.motion_wander_remaining[row] = g_gameplayEngine.rng.randf_range(1.5, 3.5)
	return motion_wander_point[row]

func clamp_to_arena(animal: AnimalEntity, point: Vector2) -> Vector2:
	return point.clamp(Vector2(12.0, 94.0), g_gameplayEngine.config.arena_size - Vector2(12.0, 58.0))

func move_towards(animal: AnimalEntity, point: Vector2, speed: float, delta: float) -> void:
	var row := animal.row
	data.motion_movement_goal[row] = point
	data.motion_speed_limit[row] = speed
	var difference := point - data.motion_position[row]
	data.motion_desired_velocity[row] = difference.normalized() * minf(speed, difference.length() / maxf(delta, 0.00001))

func submit_velocity(animal: AnimalEntity, desired: Vector2, speed: float) -> void:
	var row := animal.row
	data.motion_desired_velocity[row] = desired
	data.motion_speed_limit[row] = speed
	data.motion_movement_goal[row] = data.motion_position[row] + data.motion_desired_velocity[row]

Scripts/ECS/Systems/SheepdogSystem.gd:
class_name SheepdogSystem
extends RefCounted

var data: AnimalData

func _init(storage: AnimalData) -> void:
	data = storage

func accumulate_sheep_pressure() -> void:
	var grid: GridService = g_gameplayEngine.grid_service
	var settings: SheepConfig = g_gameplayEngine.config.sheep
	var radius: float = settings.herding_distance
	var radius_squared := radius * radius
	for source_row in g_gameplayEngine.entity_service.dog_rows:
		var source := grid.perception_positions[source_row]
		for row in grid.get_nearby_indices(source, radius, AnimalEntity.Kind.SHEEP):
			var offset := grid.perception_positions[row] - source
			var distance_squared := offset.length_squared()
			if distance_squared > radius_squared:
				continue
			data.sheep_dog_pressure[row] += offset.normalized() * (1.0 - sqrt(distance_squared) / radius)

func assign_tasks() -> void:
	var identity_entity_id := data.identity_entity_id
	var motion_position := data.motion_position
	var wolves_claimed: Dictionary = {}
	var sheep_claimed: Dictionary = {}
	var assignments: Dictionary = {}
	for dog_row in g_gameplayEngine.entity_service.dog_rows:
		var dog := data.handles[dog_row]
		if data.identity_alive[dog.row]:
			assignments[dog] = [null, null]
	# 1) Resolve nearest wolf proposals, then farthest stray proposals.
	for kind in range(2):
		var claimed: Dictionary = wolves_claimed if kind == 0 else sheep_claimed
		var waiting: Array[AnimalEntity] = []
		for dog: AnimalEntity in assignments:
			if assignments[dog][0] == null and not data.dog_returning[dog.row]:
				waiting.append(dog)
		while not waiting.is_empty():
			var proposals: Dictionary = {}
			for dog in waiting:
				var candidates: Array = data.dog_wolf_candidates[dog.row] if kind == 0 else data.dog_stray_candidates[dog.row]
				var best: AnimalEntity
				var best_score: float = INF
				for animal in candidates:
					if claimed.has(animal):
						continue
					var score := motion_position[dog.row].distance_squared_to(task_point(dog, animal)) if kind == 0 else -data.dog_protection_center[dog.row].distance_squared_to(motion_position[animal.row])
					if score < best_score or (is_equal_approx(score, best_score) and best != null and identity_entity_id[animal.row] < identity_entity_id[best.row]):
						best = animal
						best_score = score
				if best == null:
					continue
				var previous: AnimalEntity = proposals.get(best)
				var distance := motion_position[dog.row].distance_squared_to(task_point(dog, best))
				var previous_distance := motion_position[previous.row].distance_squared_to(task_point(previous, best)) if previous != null else INF
				if distance < previous_distance or (is_equal_approx(distance, previous_distance) and previous != null and identity_entity_id[dog.row] < identity_entity_id[previous.row]):
					proposals[best] = dog
			if proposals.is_empty():
				break
			for animal: AnimalEntity in proposals:
				var dog: AnimalEntity = proposals[animal]
				assignments[dog][kind] = animal
				claimed[animal] = dog
				waiting.erase(dog)
	for dog: AnimalEntity in assignments:
		apply_assignment(dog, assignments[dog][0], assignments[dog][1])

func perceive(animal: AnimalEntity, delta: float) -> void:
	var dog_assignment_remaining := data.dog_assignment_remaining
	var dog_protected_sheep := data.dog_protected_sheep
	var dog_protection_center := data.dog_protection_center
	var dog_returning := data.dog_returning
	var dog_wolf_candidates := data.dog_wolf_candidates
	var memory_target := data.memory_target
	var motion_position := data.motion_position
	var row := animal.row
	var settings: SheepdogConfig = data.settings[row]
	var common: AnimalSystem = g_gameplayEngine.animal_system
	common.perceive(animal, delta)
	dog_assignment_remaining[row] -= delta
	if not common.is_live(animal, data.live(dog_protected_sheep[row])) or dog_assignment_remaining[row] <= 0.0:
		_choose_protection_anchor(animal)
		dog_assignment_remaining[row] = settings.reassignment_interval
	_update_protection_center(animal)
	data.dog_patrol_angle[row] += settings.patrol_angular_speed * delta * (1.0 if data.identity_entity_id[row] % 2 == 0 else -1.0)
	data.dog_guard_point[row] = common.clamp_to_arena(animal, dog_protection_center[row] + Vector2.from_angle(data.dog_patrol_angle[row]) * settings.guard_distance)
	common.observe_target(animal, delta)
	if not common.is_live(animal, data.live(dog_protected_sheep[row])):
		memory_target[row] = null
		dog_returning[row] = 0
	elif motion_position[row].distance_to(dog_protection_center[row]) > settings.leash_distance:
		dog_returning[row] = 1
	if dog_returning[row] and motion_position[row].distance_to(data.dog_guard_point[row]) <= 24.0:
		dog_returning[row] = 0
	dog_wolf_candidates[row].clear()
	data.dog_stray_candidates[row].clear()
	var anchor := data.live(dog_protected_sheep[row])
	if dog_returning[row] or not common.is_live(animal, anchor):
		return
	var service: GridService = g_gameplayEngine.grid_service
	var flock: Array[Vector2] = []
	for index in service.get_nearby_indices(motion_position[anchor.row], settings.local_flock_radius, AnimalEntity.Kind.SHEEP):
		if service.perception_kinds[index] == AnimalEntity.Kind.SHEEP and motion_position[anchor.row].distance_to(service.perception_positions[index]) <= settings.local_flock_radius:
			flock.append(service.perception_positions[index])
	for wolf_row in service.get_nearby_indices(motion_position[row], settings.perception_radius, AnimalEntity.Kind.WOLF):
		var wolf := data.handles[wolf_row]
		if not data.identity_alive[wolf.row] or not common.can_see(animal, motion_position[wolf.row]):
			continue
		var threatening: bool = data.wolf_hunting[wolf.row]
		for point in flock:
			if motion_position[wolf.row].distance_to(point) < settings.threat_distance:
				threatening = true
				break
		if threatening:
			dog_wolf_candidates[row].append(wolf)
	if common.is_live(animal, data.live(memory_target[row])) and not data.memory_target_visible[row] and data.memory_unseen_elapsed[row] < settings.memory_duration:
		dog_wolf_candidates[row].append(data.live(memory_target[row]))
	var radius: float = settings.local_flock_radius
	for index in service.get_nearby_indices(motion_position[anchor.row], radius * 2.0, AnimalEntity.Kind.SHEEP):
		if service.perception_kinds[index] != AnimalEntity.Kind.SHEEP:
			continue
		var sheep := data.handles[index] as AnimalEntity
		var point := service.perception_positions[index]
		var distance := dog_protection_center[row].distance_to(point)
		var threshold: float = radius * settings.collect_complete_ratio if sheep == data.live(data.dog_collected_sheep[row]) else radius
		if motion_position[anchor.row].distance_to(point) <= radius * 2.0 and distance > threshold:
			data.dog_stray_candidates[row].append(sheep)

func task_point(animal: AnimalEntity, other: AnimalEntity) -> Vector2:
	var row := animal.row
	if other == data.live(data.memory_target[row]) and not data.memory_target_visible[row]:
		return data.memory_last_seen_position[row]
	return data.motion_position[other.row]

func apply_assignment(animal: AnimalEntity, wolf: AnimalEntity, stray: AnimalEntity) -> void:
	var memory_target := data.memory_target
	var row := animal.row
	var common: AnimalSystem = g_gameplayEngine.animal_system
	var lost_wolf: bool = common.is_live(animal, data.live(memory_target[row])) and wolf == null
	if wolf != data.live(memory_target[row]):
		memory_target[row] = wolf
		common.observe_target(animal, 0.0)
	data.dog_collected_sheep[row] = stray as AnimalEntity
	if lost_wolf:
		data.dog_returning[row] = 1

func _anchor_score(animal: AnimalEntity, sheep: AnimalEntity, anchors: PackedVector2Array) -> float:
	var row := animal.row
	var settings: SheepdogConfig = data.settings[row]
	var point := data.motion_position[sheep.row]
	var coverage: int = 0
	for anchor in anchors:
		if anchor.distance_to(point) < settings.local_flock_radius:
			coverage += 1
	return data.motion_position[row].distance_to(point) / settings.local_flock_radius + coverage * settings.coverage_weight

func _choose_protection_anchor(animal: AnimalEntity) -> void:
	var dog_protected_sheep := data.dog_protected_sheep
	var row := animal.row
	var settings: SheepdogConfig = data.settings[row]
	var common: AnimalSystem = g_gameplayEngine.animal_system
	var started := Time.get_ticks_usec() if g_gameplayEngine.profile_service.detailed_stats_enabled else 0
	var anchors := PackedVector2Array()
	for dog_row in g_gameplayEngine.entity_service.dog_rows:
		var dog := data.handles[dog_row]
		var anchor: AnimalEntity = data.live(dog_protected_sheep[dog.row])
		if dog != animal and data.identity_alive[dog.row] and anchor != null:
			anchors.append(data.motion_position[anchor.row])
	var best: AnimalEntity = data.live(dog_protected_sheep[row]) if common.is_live(animal, data.live(dog_protected_sheep[row])) else null
	var current_score: float = _anchor_score(animal, best, anchors) if best != null else INF
	var best_score := current_score
	for sheep_row in g_gameplayEngine.entity_service.sheep_rows:
		var sheep := data.handles[sheep_row]
		if not data.identity_alive[sheep.row]:
			continue
		var score: float = _anchor_score(animal, sheep, anchors)
		if score < best_score:
			best = sheep
			best_score = score

	if not common.is_live(animal, data.live(dog_protected_sheep[row])) or best_score <= current_score * (1.0 - settings.reassignment_improvement):
		dog_protected_sheep[row] = best
	if g_gameplayEngine.profile_service.detailed_stats_enabled:
		g_gameplayEngine.profile_service.record_hotspot("DogAnchor", started)

func _update_protection_center(animal: AnimalEntity) -> void:
	var motion_position := data.motion_position
	var row := animal.row
	var anchor := data.live(data.dog_protected_sheep[row])
	var settings: SheepdogConfig = data.settings[row]
	var common: AnimalSystem = g_gameplayEngine.animal_system
	if not common.is_live(animal, anchor):
		data.dog_protection_center[row] = common.get_wander_point(animal, 85.0)
		return

	data.dog_protection_center[row] = g_gameplayEngine.grid_service.sheep_center(motion_position[anchor.row], settings.local_flock_radius)

func get_debug_details(animal: AnimalEntity) -> String:
	var row := animal.row
	var common: AnimalSystem = g_gameplayEngine.animal_system
	return "Anchor #%d | Stray #%d | Unseen %.1f s" % [data.identity_entity_id[data.live(data.dog_protected_sheep[row]).row] if common.is_live(animal, data.live(data.dog_protected_sheep[row])) else 0, data.identity_entity_id[data.live(data.dog_collected_sheep[row]).row] if common.is_live(animal, data.live(data.dog_collected_sheep[row])) else 0, data.memory_unseen_elapsed[row]]

Scripts/ECS/Systems/WolfSystem.gd:
class_name WolfSystem
extends RefCounted

var data: AnimalData

func _init(storage: AnimalData) -> void:
	data = storage

func accumulate_sheep_pressure() -> void:
	var grid: GridService = g_gameplayEngine.grid_service
	var settings: SheepConfig = g_gameplayEngine.config.sheep
	var radius: float = settings.wolf_pressure_distance
	var radius_squared := radius * radius
	for source_row in g_gameplayEngine.entity_service.wolf_rows:
		var source := grid.perception_positions[source_row]
		for row in grid.get_nearby_indices(source, radius, AnimalEntity.Kind.SHEEP):
			var offset := grid.perception_positions[row] - source
			var distance_squared := offset.length_squared()
			if distance_squared > radius_squared:
				continue
			data.sheep_threat_direction[row] += offset.normalized() / maxf(sqrt(distance_squared), 1.0)
			data.sheep_threatened[row] = 1

func find_dog(animal: AnimalEntity, radius: float) -> AnimalEntity:
	var row := animal.row
	var result: AnimalEntity
	var best := radius
	for dog_row in g_gameplayEngine.entity_service.dog_rows:
		var dog := data.handles[dog_row]
		if not data.identity_alive[dog.row]:
			continue
		var distance := data.motion_position[row].distance_to(data.motion_position[dog.row])
		if distance < best or (is_equal_approx(distance, best) and result != null and data.identity_entity_id[dog.row] < data.identity_entity_id[result.row]):
			result = dog
			best = distance
	return result

func perceive(animal: AnimalEntity, delta: float) -> void:
	var wolf_resting := data.wolf_resting
	var row := animal.row
	var settings: WolfConfig = data.settings[row]
	var common: AnimalSystem = g_gameplayEngine.animal_system
	common.perceive(animal, delta)
	for index in range(4):
		data.wolf_strategy_failures[row][index] = maxf(0.0, data.wolf_strategy_failures[row][index] - settings.strategy_decay * delta)
	data.wolf_howl_elapsed[row] += delta
	if wolf_resting[row]:
		data.wolf_rest_elapsed[row] += delta
		wolf_resting[row] = int(data.wolf_rest_elapsed[row] < settings.rest_duration)
	data.wolf_nearest_threat[row] = find_dog(animal, settings.dog_threat_distance * (2.0 if data.wolf_retreating[row] else 1.0))
	if data.wolf_hunting[row]:
		data.wolf_hunt_elapsed[row] += delta
		common.observe_target(animal, delta)
		if not common.is_live(animal, data.live(data.memory_target[row])) or data.wolf_hunt_elapsed[row] >= settings.hunt_duration or (not data.memory_target_visible[row] and data.memory_unseen_elapsed[row] >= settings.memory_duration):
			end_hunt(animal, false)
	if not data.wolf_hunting[row] and not wolf_resting[row] and not common.is_live(animal, data.live(data.wolf_nearest_threat[row])) and not data.wolf_retreating[row]:
		_choose_prey(animal)

func _choose_prey(animal: AnimalEntity) -> void:
	var row := animal.row
	var settings: WolfConfig = data.settings[row]
	var common: AnimalSystem = g_gameplayEngine.animal_system
	var started := Time.get_ticks_usec() if g_gameplayEngine.profile_service.detailed_stats_enabled else 0
	var best: AnimalEntity
	var distance: float = INF
	var service: GridService = g_gameplayEngine.grid_service
	for index in service.get_nearby_indices(data.motion_position[row], settings.perception_radius, AnimalEntity.Kind.SHEEP):
		if service.perception_kinds[index] != AnimalEntity.Kind.SHEEP:
			continue
		var point := service.perception_positions[index]
		if not common.can_see(animal, point):
			continue
		var candidate := data.handles[index] as AnimalEntity
		var next_distance := data.motion_position[row].distance_squared_to(point)
		if next_distance < distance or (is_equal_approx(next_distance, distance) and best != null and data.identity_entity_id[candidate.row] < data.identity_entity_id[best.row]):
			best = candidate
			distance = next_distance
	if best != null:
		begin_hunt(animal, best)
	if g_gameplayEngine.profile_service.detailed_stats_enabled:
		g_gameplayEngine.profile_service.record_hotspot("WolfTarget", started)

func begin_hunt(animal: AnimalEntity, prey: AnimalEntity) -> void:
	var row := animal.row
	var common: AnimalSystem = g_gameplayEngine.animal_system
	data.memory_target[row] = prey
	data.wolf_hunting[row] = 1
	data.wolf_hunt_elapsed[row] = 0.0
	data.wolf_charging[row] = 0
	data.wolf_howled[row] = 0
	var total: float = 0.0
	for index in range(4):
		total += 1.0 / (1.0 + data.wolf_strategy_failures[row][index])
	var choice: float = g_gameplayEngine.rng.randf() * total
	for index in range(4):
		choice -= 1.0 / (1.0 + data.wolf_strategy_failures[row][index])
		if choice <= 0.0 or index == 4 - 1:
			data.wolf_strategy[row] = index
			break
	common.observe_target(animal, 0.0)

func end_hunt(animal: AnimalEntity, success: bool) -> void:
	var row := animal.row
	if not data.wolf_hunting[row]:
		return
	data.wolf_strategy_failures[row][data.wolf_strategy[row]] = maxf(0.0, data.wolf_strategy_failures[row][data.wolf_strategy[row]] + (-1.5 if success else 1.0))
	data.wolf_hunting[row] = 0
	data.wolf_charging[row] = 0
	data.memory_target[row] = null
	data.memory_target_visible[row] = 0
	data.wolf_resting[row] = 1
	data.wolf_rest_elapsed[row] = 0.0

func can_charge(animal: AnimalEntity) -> bool:
	var row := animal.row
	var settings: WolfConfig = data.settings[row]
	return data.wolf_hunting[row] and data.memory_target_visible[row] and (data.wolf_charging[row] or data.motion_position[row].distance_to(data.memory_last_seen_position[row]) <= settings.capture_distance * settings.charge_distance_scale)

func resolve_interactions(animal: AnimalEntity, _delta: float) -> void:
	var memory_target := data.memory_target
	var motion_position := data.motion_position
	var row := animal.row
	var settings: WolfConfig = data.settings[row]
	var common: AnimalSystem = g_gameplayEngine.animal_system
	if data.wolf_howl_pending[row]:
		data.wolf_howl_pending[row] = 0
		g_gameplayEngine.debug_service.record_howl(animal)
		for sheep_row in g_gameplayEngine.entity_service.sheep_rows:
			var sheep := data.handles[sheep_row]
			if data.identity_alive[sheep.row] and motion_position[row].distance_to(motion_position[sheep.row]) <= settings.howl_radius:
				g_gameplayEngine.sheep_system.receive_howl(sheep, motion_position[row])
	if not data.wolf_hunting[row] or data.brain_current_behavior[row] != AnimalEntity.Behavior.CHASE:
		return
	if not common.is_live(animal, data.live(memory_target[row])):
		end_hunt(animal, false)
		return
	data.wolf_nearest_threat[row] = find_dog(animal, settings.dog_threat_distance)
	if common.is_live(animal, data.live(data.wolf_nearest_threat[row])):
		end_hunt(animal, false)
		data.wolf_retreating[row] = 1
		return
	if common.can_see(animal, motion_position[data.live(memory_target[row]).row]) and motion_position[row].distance_to(motion_position[data.live(memory_target[row]).row]) <= settings.capture_distance:
		if g_gameplayEngine.entity_service.capture(data.live(memory_target[row])):
			end_hunt(animal, true)

func get_debug_details(animal: AnimalEntity) -> String:
	var row := animal.row
	return "%s | Hunt %.1f s | Unseen %.1f s | Failures %s" % [AnimalEntity.STRATEGY_NAMES[data.wolf_strategy[row]], data.wolf_hunt_elapsed[row], data.memory_unseen_elapsed[row], data.wolf_strategy_failures[row]]

